INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was versteht ein Fachinformatiker unter einem Byte?', 2, '[{"text": "Einheit aus 8 Bits", "correct": true, "because": "Grundlegende Dateneinheit"}, {"text": "Ein einzelnes Bit", "correct": false, "because": "Kleinere Einheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Byte?', 3, '[{"text": "Daten effizient speichern und verarbeiten", "correct": true, "because": "Standardgröße"}, {"text": "Kosten direkt senken", "correct": false, "because": "Indirekt"}, {"text": "Design verbessern", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Werte kann ein Byte darstellen?', 5, '[{"text": "256", "correct": true, "because": "2^8 Werte (0-255)"}, {"text": "128", "correct": false, "because": "2^7"}, {"text": "64", "correct": false, "because": "2^6"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Byte besteht aus 8 Bits. b) Es entspricht einem Bit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Byte?', 4, '[{"text": "Bitanzahl", "correct": false, "because": "Grundlage"}, {"text": "Wertbereich", "correct": false, "because": "0-255 wichtig"}, {"text": "Büroverschönerung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Byte 256 verschiedene Werte speichern kann?', 2, '[{"text": "Ja", "correct": true, "because": "2^8"}, {"text": "Nein", "correct": false, "because": "Korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Bits hat ein Byte?', 3, '[{"text": "8", "correct": true, "because": "Standarddefinition"}, {"text": "4", "correct": false, "because": "Nibble"}, {"text": "16", "correct": false, "because": "Word"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Verwendung eines Bytes?', 5, '[{"text": "Datenkodierung", "correct": true, "because": "z.B. ASCII"}, {"text": "Speicherzuweisung", "correct": true, "because": "Grundgröße"}, {"text": "Farbcodierung", "correct": false, "because": "Kein direkter Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein Byte kann einen Buchstaben speichern. b) Es ist nur für Textdaten geeignet. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Zahlen, Binärdaten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Byte unwichtig?', 4, '[{"text": "Bitsequenz", "correct": false, "because": "Definiert Wert"}, {"text": "Speicherplatz", "correct": false, "because": "Größe relevant"}, {"text": "Schriftart", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein Byte mehr als 256 Werte speichern?', 2, '[{"text": "Nein", "correct": true, "because": "2^8 = 256"}, {"text": "Ja", "correct": false, "because": "Begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Byte für Fachinformatiker?', 4, '[{"text": "Einheitliche Datengröße", "correct": true, "because": "Standardisierung"}, {"text": "Effiziente Verarbeitung", "correct": true, "because": "8 Bits"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Byte nur für Text ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Binärdaten"}, {"text": "Ja", "correct": false, "because": "Vielseitig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Byte?', 3, '[{"text": "Wertdarstellung", "correct": true, "because": "Datenkodierung"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Byte kann 256 Werte speichern. b) Es besteht aus 4 Bits.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "8 Bits, nicht 4"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein Byte?', 5, '[{"text": "Begrenzter Wertebereich", "correct": true, "because": "Nur 256 Werte"}, {"text": "Eingeschränkte Präzision", "correct": true, "because": "Für große Zahlen ungeeignet"}, {"text": "Schnellere Verarbeitung", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Fachinformatiker bei einem Byte?', 3, '[{"text": "Datenkodierung und -verarbeitung", "correct": true, "because": "Programmierung"}, {"text": "Büro reinigen", "correct": false, "because": "Kein Bezug"}, {"text": "Marketing betreiben", "correct": false, "because": "Andere Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Byte in einer Datenbank gespeichert werden?', 2, '[{"text": "Ja", "correct": true, "because": "z.B. TINYINT"}, {"text": "Nein", "correct": false, "because": "Unterstützt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Wertbereich entspricht einem Byte?', 4, '[{"text": "0 bis 255", "correct": true, "because": "2^8"}, {"text": "0 bis 127", "correct": false, "because": "7 Bits"}, {"text": "0 bis 15", "correct": false, "because": "4 Bits"}]');
